import test from "node:test";
import assert from "node:assert/strict";
import { slugify } from "../src/slug.js";

test("slugify converts spaces and capital letters", () => {
	assert.equal(slugify("Hello World"), "hello-world");
	assert.equal(slugify("  Multiple   Words  "), "multiple-words");
});

import { test } from "node:test";
import assert from "node:assert/strict";
import { slugify } from "./slug.js";

test("replaces spaces with hyphens", () => {
	assert.equal(slugify("hello world"), "hello-world");
});

test("collapses consecutive whitespace into one hyphen", () => {
	assert.equal(slugify("hello   big \t world"), "hello-big-world");
});

test("trims leading and trailing spaces", () => {
	assert.equal(slugify("  hello world  "), "hello-world");
});

test("lowercases capital letters", () => {
	assert.equal(slugify("Hello World"), "hello-world");
	assert.equal(slugify("HELLO"), "hello");
});

